  const overlap=(a,b)=>a.x<b.x+b.w&&a.x+a.w>b.x&&a.y<b.y+b.h&&a.y+a.h>b.y;
  function layers(map){return (maps[map]||[]).map(([cell,x,y,w,h,flip])=>({cell,x,y,w,h,flip:!!flip}));}
