add('accept-tower-duty','tower-duty','garden','qingwei','接下锁妖塔当值','accept',{detail:'先完成回山呈证；清微转交值役铜镜与符验。二者是登记工具，不是可消耗战斗物。',grant:grant({}, {},['duty-mirror','duty-talisman'])});
