A('take-seal-clay','tower-seal','tower-seal','towerSealClay','取本次复封朱泥','只取一盒按此裂缝配好的朱泥，不进入可炼制材料库存。',{marks:['clay-taken'],requires:requires([done('tower-seal','fracture-read'),sealChoice('repair')]),grant:grant({}, {'seal-clay':1})});
for(const [id,objectId,label]of [['seal-west','towerSealWest','西锚定外环'],['seal-middle','towerSealMiddle','中锚留回流'],['seal-east','towerSealEast','东锚合封缄']])add(id,'tower-seal','tower-seal',objectId,label,'sequence',{detail:'依次西、中、东；错误次序复位，不耗朱泥。第三锚正确时才整份用去朱泥。',requires:requires([done('tower-seal','fracture-read'),done('tower-seal','clay-taken'),sealChoice('repair')]),...(id==='seal-east'?{marks:['seal-set'],cost:cost({}, {'seal-clay':1})}:{})});
add('defend-seal-rift','tower-seal','tower-seal','towerSealBell','敲铃守住复封窗口','battle',{detail:'两名失控阵灵逼近；可自动迎敌并以V暂停下令。开战不扣任务物，普通符药按实际施用消耗。',requires:requires([done('tower-seal','seal-set'),sealChoice('repair')]),marks:['rift-held','seal-resolved'],encounter:'seal-rift'});
A('bypass-measure-west','tower-seal','tower-seal','towerSealWest','测西锚回流间隙','观察西锚三次回流并把最弱的一线标在值查图上；静行仍须核另一侧，不能只凭口述越禁。',{marks:['bypass-west'],requires:requires([sealChoice('bypass'),proof('fox-testimony'),proof('bear-testimony'),proof('seal-slip')])});
A('bypass-measure-east','tower-seal','tower-seal','towerSealEast','核东锚静隙','走到东侧把回流方向与西锚记录相对照；不消耗朱泥，也不惊动阵灵。',{marks:['bypass-east'],requires:requires([sealChoice('bypass'),done('tower-seal','bypass-west')])});
A('bypass-combine-standard','tower-seal','tower-seal','towerSealMiddle','合成两侧静行图','两侧观测在中锚相合，确认每一步都落在回流间隙；这是所有来处和专长都能完成的普通方法。',{marks:['bypass-standard','bypass-traced'],requires:requires([sealChoice('bypass'),done('tower-seal','bypass-west'),done('tower-seal','bypass-east')])});
const bypassMethods=[
  ['rain','backgroundMission','towerSealNotice','以行路记分清两份证词','已办雨夜行路记，把老狐的提醒与熊妖所见分栏；对照西锚实测找到能互相印证的静隙，不把传闻当事实。'],
  ['poor','backgroundMission','towerSealClay','以共灶核份经验核朱泥用量','已办共灶委托，能从值查图的定额与匣内旧泥残量辨出未受扰动的锚侧；只查看公用匣，不取朱泥或补发粮契。'],
  ['beggar','backgroundMission','towerSealUp','沿旧脚印核安全落点','已办街巷递送人委托，循干净落脚点与回头痕核对西锚记录，找到既有静行线；旧结绳不再授予，也没有隐身能力。'],
  ['caravan','backgroundMission','towerSealNotice','以药路核签经验验交班次序','已结药路委托，对照值查图的交班签序与西锚实测，识出不会撞上阵灵回流的窗口；不重发已交封签。'],
  ['demon','backgroundMission','towerSealCrack','以边药查伪经验辨灵流外缘','已办魔域独立回报，按查伪符所用的内外纹序复核裂痕与西锚；辨出静行外缘，不改阵营，也不把魔域来处当善恶。'],
  ['sword','originTraining','towerSealMiddle','以回风剑页辨回流节律','已完成剑庐试炼，用所学回风节律核对西锚的收放，在中锚辨出可通行的间隙；不强行斩封印。'],
  ['medicine','originTraining','towerSealClay','以药庐辨材核锚侧湿度','已完成药庐试炼，结合西锚记录与旧泥干湿判断哪侧尚未被扰动；只辨材，不消耗药囊或任何普通草药。'],
  ['scholar','originTraining','towerSealNotice','以经阁定脉补齐静行图','已完成经阁试炼，按定脉所学从西锚与旧图推回另一侧的回流位置；仍须到铜铃复核，不直接越层。']
];
for(const [id,type,objectId,label,detail]of bypassMethods)A('bypass-method-'+id,'tower-seal','tower-seal',objectId,label,detail,{marks:['bypass-'+id,'bypass-traced'],requires:requires([sealChoice('bypass'),done('tower-seal','bypass-west'),{type,id}])});
A('confirm-seal-bypass','tower-seal','tower-seal','towerSealBell','以证词和静行图核准通路','西锚实测与现场核验相合；以不触发阵灵的节律经过侧阶。只记录静行通路核准，不记录复封、耗泥或击败敌人。',{marks:['bypass-held','seal-resolved'],requires:requires([sealChoice('bypass'),done('tower-seal','bypass-traced'),proof('fox-testimony'),proof('bear-testimony'),proof('seal-slip')])});
add('claim-tower-seal','tower-seal','tower-seal','towerSealNotice','交还值查图，收通行复验记','claim',{detail:'守阵或静行择一完成后，在值查图旁一次领护身符与七层准记。两路不能双领；绕行无战斗掉落，守阵清敌也不即时掉普通材料。',grant:grant({ward:1},{},['upper-pass'])});

add('accept-tower-trace','tower-trace','tower-upper','towerUpperNotice','开始七层留证','accept',{detail:'铜镜只是观察工具。残响身份未核，不交魂、不照录许诺，也不凭幻相认定他人伤亡。'});
A('take-rubbing-paper','tower-trace','tower-upper','towerUpperRubbingKit','取一张封缄拓纸','拓纸专供本次残字，不可制符，未取纸不能将血字当作已留证。',{marks:['paper-taken'],grant:grant({}, {'rubbing-paper':1})});
for(const [id,objectId,label]of [['mirror-edge','towerUpperMirror','先核镜框与手中铜镜'],['mirror-light','towerUpperLamp','移到侧灯核对投影'],['mirror-present','towerUpperMirror','再以眼前人事辨明幻相']])add(id,'tower-trace','tower-upper',objectId,label,'sequence',{detail:'依次验镜框、侧光和眼前人事；错序可重来，不消耗镜子。镜中恐吓不等于灵薇实际遇险。',requires:requires([token('duty-mirror')]),...(id==='mirror-present'?{marks:['mirror-verified'],grant:grant({}, {},[],['mirror-illusion'])}:{})});
A('copy-wall-blood','tower-trace','tower-upper','towerUpperBlood','按原样拓下血字与残笔','只拓可见字迹，不把残缺三点水补作姓名。用去本次封缄拓纸。',{marks:['blood-copied'],requires:requires([done('tower-trace','paper-taken'),done('tower-trace','mirror-verified')]),cost:cost({}, {'rubbing-paper':1}),grant:grant({}, {},[],['wall-blood'])});
for(const [id,choice,label,detail]of [
  ['refuse-echo','refuse','温和拒绝换魄','谢谢提醒，但不能以魂魄换未经证明的话。此刻不认残响身份，也不把它的话写成案情结论。'],
  ['record-echo','record','只记录交易要求','我会记录你索要一魄，但不会答应；你所声称的身份和真相，留待独立查证。']
])add(id,'tower-trace','tower-upper','towerUnknownEcho',label,'choice',{choice,detail,confirm:{title:'确认留证方式',text:detail+' 此次回应会记入案卷，两种方式同样推进且同奖；取消可再考虑。',label:'确认此回应'},marks:['voice-bounded'],requires:requires([done('tower-trace','blood-copied')])});
A('find-tower-tunnel','tower-trace','tower-upper','towerTunnelLock','核对铜锁与密道方向','凌云子取出铜钥，说明通道回到师父住处。确认路线，不把钥匙变成可卖的法宝。',{marks:['tunnel-found'],requires:requires([done('tower-trace','voice-bounded')])});
A('hear-lingyun','tower-trace','tower-upper','towerLingyun','让师兄将所知具名说清','他承认早知密道，并称陈玄受心蛊控制。林墨把“师兄所说”与“亲眼所见”分开，要求回山复核；不提前认定残响身份。',{marks:['lingyun-heard'],requires:requires([done('tower-trace','tunnel-found')]),grant:grant({}, {},[],['tunnel-witness'])});
add('claim-tower-trace','tower-trace','tower-upper','towerLingyun','封存笔录，沿密道回山','claim',{detail:'线索保留为证据与疑点；清心散一份作为回程照护，不因残响选择不同而改变。',grant:grant({qingxin:1})});

add('accept-tower-review','tower-review','garden','qingwei','请清微复核塔中见闻','accept',{detail:'两位塔中证人、封印、铜镜、血字与凌云子口述逐项列开。'});
A('compare-tower-records','tower-review','garden','qingwei','区分事实、证词和未决疑点','清微确认旧案仍需追查。血字残笔不补名，陈玄心蛊说法仍待独立证据；残响身份与更深秘密暂不宣判。',{marks:['review-recorded'],requires:requires([proof('fox-testimony'),proof('bear-testimony'),proof('seal-slip'),proof('mirror-illusion'),proof('wall-blood'),proof('tunnel-witness')]),grant:grant({}, {},[],['master-review'])});
add('claim-tower-review','tower-review','garden','qingwei','收好复核副卷','claim',{detail:'取得副卷并可继续准备金丹；杏花村照护是可选去向，不以亲近任何人换主线资格。',grant:grant({tea:1},{},['tower-case-copy'])});

add('accept-apricot-aid','apricot-aid','apricot-village','apricotAxing','与阿杏一起照看行旅','accept',{detail:'阿杏二十二岁，先说明病人的情况与她自己的判断。林墨可帮忙辨药与照护，不替她决定人生。'});
A('read-apricot-case','apricot-aid','apricot-village','apricotCasebook','先看病案与药样辨识图','只取指定鲜药样。阿杏逐项标出叶脉、气味与应采部位，不把普通草药画成发光灵物。',{marks:['case-read']});
for(const [side,objectId]of [['west','apricotHerbWest'],['east','apricotHerbEast']])A('gather-apricot-'+side,'apricot-aid','apricot-village',objectId,'按病案采一份退热药样','本次病案只取这一处一份，采后记录来源；不是普通青灵草的隐藏备用库存。',{marks:[side+'-sample'],requires:requires([done('apricot-aid','case-read')]),grant:grant({}, {'fever-sample':1})});
A('draw-apricot-water','apricot-aid','apricot-village','apricotWell','用净瓶量取一份煎药水','净瓶已按病案定量，专供这一份汤剂，不与普通山泉水库存混用。',{marks:['water-drawn'],requires:requires([done('apricot-aid','case-read')]),grant:grant({}, {'decoction-water':1})});
for(const [id,label]of [['apricot-crush','先分拣轻捣鲜药样'],['apricot-soak','再以净煎水润药'],['apricot-simmer','最后文火净煎成药']])add(id,'apricot-aid','apricot-village','apricotBench',label,'sequence',{detail:'依次分拣、润药、净煎；错序重来不扣料，正确最后一步才用去两份鲜药样与一瓶净煎水。',requires:requires([done('apricot-aid','west-sample'),done('apricot-aid','east-sample'),done('apricot-aid','water-drawn')]),...(id==='apricot-simmer'?{marks:['medicine-brewed'],cost:cost({}, {'fever-sample':2,'decoction-water':1})}:{})});
A('deliver-apricot-care','apricot-aid','apricot-village','apricotPatient','把温药送到病榻并协助照护','阿杏复核用量后与林墨一起照护；行旅退热后可自行安排回家。成药不进入普通战斗库存，不会因误饮而使任务卡住。',{marks:['care-delivered'],requires:requires([done('apricot-aid','medicine-brewed')])});
for(const [id,choice,label,detail]of [
  ['apricot-friend','friend','以朋友相待，约好下次共事','阿杏愿意把你当作可商量医案的朋友。共同医案与实用谢礼照常取得，不额外判好坏。'],
  ['apricot-close','close','明确回应：我愿多了解你','阿杏愿意慢慢相识，也保留自己的药圃与目标。双方成年；此刻只确认亲近意愿，不自动恋爱、同居或结契。']
])add(id,'apricot-aid','apricot-village','apricotAxing',label,'choice',{choice,detail,confirm:{title:choice==='friend'?'确认以朋友相待':'确认愿再相见',text:detail+' 两种选择均得回气丹、温养茶和医案札，不影响主线；取消不会写入关系。',label:choice==='friend'?'确认朋友':'确认亲近意愿'},marks:['bond-defined'],requires:requires([done('apricot-aid','care-delivered')])});
add('claim-apricot-aid','apricot-aid','apricot-village','apricotAxing','共同署名，收好医案与谢礼','claim',{detail:'朋友与亲近完全同奖：回气丹一枚、温养茶一份、春雨医案札；奖励放不下可稍后来取。',grant:grant({potion:1,tea:1},{},['apricot-case-notes'])});

add('accept-m2-handoff','m2-handoff','garden','qingwei','请教下一步结丹准备','accept',{detail:'只要求锁妖塔案卷已复核；未去杏花村、未选择亲近也可继续。'});
