      const status=g.sectWorldStatus(),panel=current==='hub'?null:g.sectWorldPanel(current);
      const title=panel?.title||'合欢宗 · 行旅药站',subtitle=panel?.subtitle||'可以亲自走访的庭院 · 三事由你决定';
      let body;
