        c.beginPath();c.moveTo(h.x+Math.cos(ang)*(h.r-9),h.y+Math.sin(ang)*(h.r-9));c.lineTo(h.x+Math.cos(ang)*(h.r-1),h.y+Math.sin(ang)*(h.r-1));
